// Orchestration. Everything here is driven by trusted inputs only: the event
// payload generated by GitHub, the configuration and agreement documents on
// the default branch, and the signature store. Pull request code is never
// checked out, built or executed.

import { createHash } from "node:crypto";
import { parseConfig, type AgreementConfig, type Config, type StorageConfig } from "./config.ts";
import { collectContributors } from "./contributors.ts";
import { evaluate, type Verdict } from "./evaluate.ts";
import { COMMENT_MARKER, renderComment, statusDescription, type DocumentLinks } from "./report.ts";
import { parseComment } from "./signing.ts";
import { SignatureStore, type SignatureEntry } from "./store.ts";
import type { Account, RepoPort, StorePort } from "./types.ts";

export const MAX_COMMITS = 250;
export const MAX_SWEEP = 100;

export interface Context {
  eventName: string;
  // The webhook payload as delivered by GitHub (GITHUB_EVENT_PATH).
  payload: Record<string, any>;
  serverUrl: string;
  runUrl: string;
  configPath: string;
  /** Optional explicit PR number (workflow_dispatch). */
  pullRequest?: number;
}

export interface Logger {
  info(message: string): void;
  warning(message: string): void;
}

export interface Outcome {
  result: "passed" | "failed" | "skipped" | "signed" | "mixed";
  unsigned: string[];
  checked: number[];
  message: string;
}

export interface LoadedDocument {
  path: string;
  sha256: string;
  url: string;
}

export function sha256(data: Buffer | string): string {
  return createHash("sha256").update(data).digest("hex");
}

export class PactDock {
  readonly #ctx: Context;
  readonly #repo: RepoPort;
  readonly #makeStore: (storage: StorageConfig) => Promise<StorePort>;
  readonly #log: Logger;
  readonly #now: () => Date;
  /** Head SHA currently being evaluated, so failures can be reported on it (fail closed). */
  currentSha: string | null = null;
  config: Config | null = null;

  constructor(ctx: Context, repo: RepoPort, makeStore: (storage: StorageConfig) => Promise<StorePort>, log: Logger, now: () => Date = () => new Date()) {
    this.#ctx = ctx;
    this.#repo = repo;
    this.#makeStore = makeStore;
    this.#log = log;
    this.#now = now;
  }

  async run(): Promise<Outcome> {
    const { eventName, payload } = this.#ctx;
    if (eventName === "pull_request_target" || eventName === "pull_request") {
      // pull_request is only accepted for completeness; examples use pull_request_target
      // so the workflow definition always comes from the default branch.
      this.currentSha = payload["pull_request"]?.head?.sha ?? null;
    }
    const setup = await this.#setup();

    switch (eventName) {
      case "pull_request_target":
      case "pull_request": {
        const number = payload["pull_request"]?.number;
        if (!Number.isInteger(number)) throw new Error("Event payload has no pull request number.");
        return this.#single(setup, number);
      }
      case "issue_comment":
        return this.#onComment(setup);
      case "workflow_dispatch":
      case "schedule":
        if (this.#ctx.pullRequest) return this.#single(setup, this.#ctx.pullRequest);
        return this.#sweep(setup);
      default:
        throw new Error(`PactDock does not handle the "${eventName}" event.`);
    }
  }

  async #setup(): Promise<Setup> {
    const head = await this.#repo.getDefaultBranchHead();
    const raw = await this.#repo.getFile(this.#ctx.configPath, head.sha);
    if (!raw) throw new Error(`Configuration file ${this.#ctx.configPath} was not found on the default branch (${head.branch}).`);
    const config = parseConfig(raw.toString("utf8"));
    this.config = config;
    const individual = await this.#loadDocument(config.individual, head.sha);
    const entity = config.entity ? await this.#loadDocument(config.entity, head.sha) : undefined;
    const store = new SignatureStore(await this.#makeStore(config.storage), config.storage.directory);
    const links: DocumentLinks = { individualUrl: individual.url };
    if (entity) links.entityUrl = entity.url;
    return { config, store, individual, entity, links };
  }

  async #loadDocument(agreement: AgreementConfig, ref: string): Promise<LoadedDocument> {
    const content = await this.#repo.getFile(agreement.document, ref);
    if (!content) throw new Error(`Agreement document ${agreement.document} was not found on the default branch.`);
    const digest = sha256(content);
    if (agreement.sha256 && agreement.sha256 !== digest) {
      throw new Error(
        `Agreement document ${agreement.document} does not match the pinned sha256 (found ${digest}). Bump the version or update the pin deliberately.`,
      );
    }
    const url = `${this.#ctx.serverUrl}/${this.#repo.owner}/${this.#repo.repo}/blob/${ref}/${agreement.document}`;
    return { path: agreement.document, sha256: digest, url };
  }

  async #single(setup: Setup, number: number): Promise<Outcome> {
    const verdict = await this.check(setup, number);
    if (!verdict) return { result: "skipped", unsigned: [], checked: [], message: `Pull request #${number} is closed.` };
    return {
      result: verdict.passed ? "passed" : "failed",
      unsigned: verdict.unsigned.map((c) => c.login),
      checked: [number],
      message: statusDescription(verdict),
    };
  }

  async #sweep(setup: Setup): Promise<Outcome> {
    const numbers = await this.#repo.listOpenPullRequests(MAX_SWEEP);
    const unsigned = new Set<string>();
    let failed = 0;
    const errors: string[] = [];
    for (const number of numbers) {
      try {
        const verdict = await this.check(setup, number);
        if (verdict && !verdict.passed) {
          failed++;
          verdict.unsigned.forEach((c) => unsigned.add(c.login));
        }
      } catch (err) {
        errors.push(`#${number}: ${(err as Error).message}`);
        if (this.currentSha) await this.#reportError(setup.config, this.currentSha, err as Error);
      }
    }
    if (errors.length) throw new Error(`Recheck failed for ${errors.length} pull request(s): ${errors.join("; ")}`);
    return {
      result: failed ? "mixed" : "passed",
      unsigned: [...unsigned],
      checked: numbers,
      message: `Rechecked ${numbers.length} open pull request(s); ${failed} still need signatures.`,
    };
  }

  /** Evaluates one pull request and publishes the status (and comment). Returns null if closed. */
  async check(setup: Setup, number: number): Promise<Verdict | null> {
    const { config } = setup;
    const pr = await this.#repo.getPullRequest(number);
    if (pr.state !== "open") return null;
    const history = await this.#repo.getPullRequestCommits(number, MAX_COMMITS);
    const sha = history.headSha || pr.headSha;
    this.currentSha = sha;
    await this.#repo.setStatus(sha, "pending", config.statusContext, "Checking CLA signatures…", this.#ctx.runUrl);

    const set = collectContributors(pr, history, { coAuthors: config.coAuthors, committers: config.committers, maxCommits: MAX_COMMITS });
    const verdict = await evaluate(config, set, setup.store);
    await this.#repo.setStatus(sha, verdict.passed ? "success" : "failure", config.statusContext, statusDescription(verdict), pr.htmlUrl);
    this.#log.info(`#${number} @ ${sha.slice(0, 7)}: ${statusDescription(verdict)}`);
    if (config.comment) await this.#upsertComment(number, renderComment(config, verdict, setup.links), verdict.passed);
    return verdict;
  }

  async #upsertComment(number: number, body: string, passed: boolean): Promise<void> {
    const comments = await this.#repo.listComments(number);
    // Only our own comments (posted by a bot) are ever updated.
    const existing = comments.find((c) => c.user.type === "Bot" && c.body.startsWith(COMMENT_MARKER));
    if (!existing) {
      if (!passed) await this.#repo.createComment(number, body);
      return;
    }
    if (existing.body !== body) await this.#repo.updateComment(existing.id, body);
  }

  async #reportError(config: Config, sha: string, err: Error): Promise<void> {
    try {
      await this.#repo.setStatus(sha, "error", config.statusContext, `PactDock error: ${err.message}`.slice(0, 140), this.#ctx.runUrl);
    } catch {
      // Ignore: a missing or non-success status still blocks merging.
    }
  }

  async #onComment(setup: Setup): Promise<Outcome> {
    const { payload } = this.#ctx;
    const skip = (message: string): Outcome => {
      this.#log.info(message);
      return { result: "skipped", unsigned: [], checked: [], message };
    };
    const issue = payload["issue"];
    const comment = payload["comment"];
    if (!issue?.pull_request) return skip("Comment is not on a pull request.");
    if (payload["action"] !== "created") return skip(`Ignoring comment "${payload["action"]}" event; only new comments can sign.`);

    const { config } = setup;
    const intent = parseComment(String(comment?.body ?? ""), config.individual, config.entity);
    if (intent.kind === "none") return skip("Comment is not a PactDock command or signature.");

    const number: number = issue.number;
    const commenter: Account & { type: string } = { id: comment.user.id, login: comment.user.login, type: comment.user.type };
    if (payload["sender"]?.id !== commenter.id) return skip("Comment sender and author differ; ignoring.");
    if (intent.kind === "recheck") return this.#single(setup, number);
    if (commenter.type !== "User") return skip("Only user accounts can sign agreements.");

    // Re-read the comment from the API: it must still exist, be unedited and match the payload.
    const live = await this.#repo.getComment(comment.id);
    if (!live || live.user.id !== commenter.id || live.body !== comment.body || live.updatedAt !== live.createdAt) {
      return skip("Signing comment was edited or deleted before it could be verified; please post a new comment.");
    }

    const pr = await this.#repo.getPullRequest(number);
    if (pr.state !== "open") return skip(`Pull request #${number} is closed; signatures are only accepted on open pull requests.`);
    const history = await this.#repo.getPullRequestCommits(number, MAX_COMMITS);
    const set = collectContributors(pr, history, { coAuthors: config.coAuthors, committers: config.committers, maxCommits: MAX_COMMITS });
    if (!set.contributors.some((c) => c.id === commenter.id)) {
      await this.#repo.addReaction(comment.id, "confused");
      return skip(`@${commenter.login} is not a contributor to #${number}; signature not recorded.`);
    }

    const agreement = intent.kind === "entity" ? config.entity! : config.individual;
    const doc = intent.kind === "entity" ? setup.entity! : setup.individual;
    const signer: Account = { id: commenter.id, login: commenter.login };
    const entry: SignatureEntry = {
      agreementId: agreement.id,
      agreementName: agreement.name,
      version: agreement.version,
      documentPath: doc.path,
      documentSha256: doc.sha256,
      documentUrl: doc.url,
      signedAt: live.createdAt,
      recordedAt: this.#now().toISOString(),
      signer,
      evidence: {
        method: "pull-request-comment",
        repository: `${this.#repo.owner}/${this.#repo.repo}`,
        repositoryId: payload["repository"]?.id,
        pullRequest: number,
        commentId: live.id,
        commentUrl: live.htmlUrl,
        commentBody: live.body,
        commentSha256: sha256(live.body),
        workflowRunUrl: this.#ctx.runUrl,
      },
    };
    const where = `${this.#repo.owner}/${this.#repo.repo}#${number}`;
    const result =
      intent.kind === "entity"
        ? await setup.store.appendEntity(
            agreement,
            intent.entityName,
            entry,
            `PactDock: entity ${agreement.id} v${agreement.version} for "${intent.entityName}" signed by @${signer.login} (${signer.id}) via ${where}`,
          )
        : await setup.store.appendIndividual(
            agreement,
            signer,
            entry,
            `PactDock: ${agreement.id} v${agreement.version} signed by @${signer.login} (${signer.id}) via ${where}`,
          );
    this.#log.info(`Signature ${result} for @${signer.login} (${signer.id}) in ${setup.store.label}.`);
    await this.#repo.addReaction(comment.id, "+1");

    const outcome = await this.#single(setup, number);
    return { ...outcome, result: outcome.result === "passed" ? "passed" : "signed" };
  }

  async reportFailure(err: Error): Promise<void> {
    if (this.config && this.currentSha) await this.#reportError(this.config, this.currentSha, err);
    else if (this.currentSha) {
      // Configuration failed to load: use the default context so required checks stay blocked visibly.
      try {
        await this.#repo.setStatus(this.currentSha, "error", "PactDock CLA", `PactDock error: ${err.message}`.slice(0, 140), this.#ctx.runUrl);
      } catch {
        // ignore
      }
    }
  }
}

interface Setup {
  config: Config;
  store: SignatureStore;
  individual: LoadedDocument;
  entity: LoadedDocument | undefined;
  links: DocumentLinks;
}
